/*
 * Combines the scripts referenced by runner.js into one parser-blocking file.
 * Run from the runtime root: node scripts/build-runtime-bundle.js
 */
const fs = require("fs");
const path = require("path");

const runtimeRoot = path.resolve(__dirname, "..");
const runnerPath = path.join(__dirname, "runner.js");
const manifestPath = path.join(__dirname, "runtime.bundle.manifest.json");
const scriptPaths = JSON.parse(fs.readFileSync(manifestPath, "utf8"));

if (scriptPaths.length === 0) {
    throw new Error("The runtime bundle manifest is empty.");
}

const bundle = [
    "/* GameMaker HTML5 Runtime bundle. Generated by scripts/build-runtime-bundle.js. */",
    "/* Source order is preserved because the runtime uses global scripts. */",
    ""
];

for (const scriptPath of scriptPaths) {
    const sourcePath = path.join(runtimeRoot, scriptPath);
    if (!fs.existsSync(sourcePath)) {
        throw new Error(`Referenced runtime source does not exist: ${scriptPath}`);
    }

    bundle.push(`\n/* ===== BEGIN ${scriptPath} ===== */\n`);
    bundle.push(fs.readFileSync(sourcePath, "utf8"));
    bundle.push(`\n/* ===== END ${scriptPath} ===== */\n`);
}

fs.writeFileSync(path.join(__dirname, "runtime.bundle.js"), bundle.join(""), "utf8");
fs.writeFileSync(runnerPath, [
    "// GameMaker HTML5 Runtime bootstrap.",
    `// The original ${scriptPaths.length} synchronous script requests are combined into one file.`,
    "// Source order is preserved in scripts/runtime.bundle.js.",
    "document.write('<script type=\"text/javascript\" src=\"scripts/runtime.bundle.js\"></script>');",
    ""
].join("\n"), "utf8");

console.log(`Built runtime.bundle.js from ${scriptPaths.length} runtime scripts.`);
